// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function testFuzz_property(address recipient, uint256 amount) public {
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 afterFirst = c.proposalCount();
        assertTrue(afterFirst == before + 1, "proposalCount must increment by one per new grant proposal");
    }
}
